package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.transaction.annotation.Transactional;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Import(LegacyBankJdbcTestConfiguration.class) @Transactional("legacyBankTestTransactions") @EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true")
class LegacyMonthlyRangeLocalDatabaseTest {
 @Autowired FeatureStore store;LegacyMonthlyReportLocalDatabaseTest f;
 @BeforeEach void setup(){f=new LegacyMonthlyReportLocalDatabaseTest();f.store=store;f.setup();}
 @Test void rangeUsesExactInclusiveSecondsAndOriginalDateTitle(){f.detail("12.50",0,0);f.detail("99.00",0,1);var before=store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.order);var result=f.service.rangeDraft(f.hospital,"2024-02-10T08:30:00","2024-02-29T23:59:59",null,null);assertEquals(2,((Number)result.get("count")).intValue());assertEquals("12.50",result.get("unpaid"));assertEquals("",result.get("month"));assertEquals("2024-02-10-2024-02-29"+f.prefix+"德国纳博科临实验室账单",result.get("title"));assertEquals(result.get("title"),result.get("pdfTitle"));assertEquals(0,((Number)f.service.rangeDraft(f.hospital,"2024-02-10T08:30:00","2024-02-29T23:59:58",null,null).get("count")).intValue());assertEquals(2,((Number)f.service.rangeDraft(f.hospital,"2024-02-29T23:59:59","2024-02-29T23:59:59",null,null).get("count")).intValue());assertEquals(before,store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.order));assertEquals(0,store.jdbc().queryForObject("SELECT COUNT(*) FROM lin_lb_noticemail WHERE HospId=?",Integer.class,f.hospital));}
 @Test void rangeTemplatesUseDateLabelsButDoNotExpandQueryToWholeDays(){f.detail("8.25",0,0);long template=store.insert("INSERT INTO lin_lb_dictfinancereport(model_name,model_content) VALUES(?,?)",f.prefix,"{起始时间}|{结束时间}|{结算月份}|{总费用}");var result=f.service.rangeDraft(f.hospital,"2024-02-29T23:59:59","2024-03-01T01:00:00",template,null);assertTrue(result.get("reportHtml").toString().contains("2024-02-29|2024-03-01|2024年02月|8.25"));assertEquals(0,((Number)f.service.rangeDraft(f.hospital,"2024-03-01T00:00:00","2024-03-01T01:00:00",template,null).get("count")).intValue());}
 @Test void invalidOrReversedRangesAndClosedGateAreRejected(){for(String value:new String[]{"2024-02-30T12:00:00","2024-02-01","not-date","0000-01-01T00:00:00"})assertEquals(400,assertThrows(BusinessException.class,()->f.service.rangeDraft(f.hospital,value,"2024-03-01T00:00:00",null,null)).getCode());assertEquals(400,assertThrows(BusinessException.class,()->f.service.rangeDraft(f.hospital,"2024-03-02T00:00:00","2024-03-01T00:00:00",null,null)).getCode());f.gate(false);assertEquals(409,assertThrows(BusinessException.class,()->f.service.rangeDraft(f.hospital,"2024-02-01T00:00:00","2024-03-01T00:00:00",null,null)).getCode());}
}
